import math

def calculate_C(ax, ay):
    """Calculates C_xy = (a_x * a_y - 1) / (a_x - a_y)"""
    if ax == ay:
        raise ValueError("a_x must not equal a_y")
    return (ax * ay - 1) / (ax - ay)

def calculate_Ax(A, x):
    """Calculates P_x = product_{y!=x} C_xy for a given list A."""
    P_x = 1.0
    for y in range(len(A)):
        if y != x:
            P_x *= calculate_C(A[x], A[y])
    return P_x

def calculate_A_i(A):
    """Calculates A_i = sum_{x=1}^{N} P_x where N = len(A)."""
    A_i = 0.0
    for x in range(len(A)):
        A_i += calculate_Ax(A, x)
    return A_i

# Set up the values for A_3 (N=4)
# a_i = 3^i
a = [3**i for i in range(1, 5)] # a[0]=3^1, a[1]=3^2, a[2]=3^3, a[3]=3^4
print(f"A = {a}")

# Calculate A_3
A3 = calculate_A_i(a)
print(f"A_3 = {A3}")

